--
-- Name: tattoos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tattoos (
    tattoo_seq bigint NOT NULL,
    registrant_seq integer NOT NULL,
    image_seq bigint NOT NULL,
    source_type character varying(20) NOT NULL,
    primary_style_seq integer NOT NULL,
    secondary_style_1_seq integer,
    secondary_style_2_seq integer,
    rendering_style_1_seq integer,
    rendering_style_2_seq integer,
    color_seq integer,
    is_used_for_training boolean DEFAULT false NOT NULL,
    trained_dttm timestamp with time zone,
    reg_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    mod_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_tattoos_rendering_distinct CHECK (((rendering_style_1_seq IS NULL) OR (rendering_style_2_seq IS NULL) OR (rendering_style_1_seq <> rendering_style_2_seq))),
    CONSTRAINT ck_tattoos_rendering_order CHECK (((rendering_style_2_seq IS NULL) OR (rendering_style_1_seq IS NOT NULL))),
    CONSTRAINT ck_tattoos_secondary_distinct CHECK (((secondary_style_1_seq IS NULL) OR (secondary_style_2_seq IS NULL) OR (secondary_style_1_seq <> secondary_style_2_seq))),
    CONSTRAINT ck_tattoos_secondary_order CHECK (((secondary_style_2_seq IS NULL) OR (secondary_style_1_seq IS NOT NULL))),
    CONSTRAINT ck_tattoos_source_type CHECK (((source_type)::text = ANY ((ARRAY['DEFAULT'::character varying, 'USER_POST'::character varying, 'USER_COLLECTION'::character varying, 'USER_EXTRACTION'::character varying])::text[]))),
    CONSTRAINT ck_tattoos_training CHECK ((((is_used_for_training = true) AND (trained_dttm IS NOT NULL)) OR ((is_used_for_training = false) AND (trained_dttm IS NULL))))
);


--
-- Name: tattoos_tattoo_seq_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.tattoos ALTER COLUMN tattoo_seq ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.tattoos_tattoo_seq_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: user_account_status_histories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_account_status_histories (
    account_status_history_seq bigint NOT NULL,
    user_seq integer NOT NULL,
    previous_status character varying(12),
    changed_status character varying(12) NOT NULL,
    reason_type character varying(20) NOT NULL,
    reason_detail character varying(1000),
    expired_dttm timestamp with time zone,
    reg_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    reg_usr_seq integer,
    CONSTRAINT ck_account_histories_actor CHECK (((((reason_type)::text = 'SUSPENSION_EXPIRED'::text) AND ((changed_status)::text = 'ACTIVE'::text) AND (reg_usr_seq IS NULL)) OR (((reason_type)::text <> 'SUSPENSION_EXPIRED'::text) AND (reg_usr_seq IS NOT NULL)))),
    CONSTRAINT ck_account_histories_changed_status CHECK (((changed_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying, 'BANNED'::character varying, 'WITHDRAWN'::character varying])::text[]))),
    CONSTRAINT ck_account_histories_expiry CHECK (((((changed_status)::text = 'SUSPENDED'::text) AND (expired_dttm IS NOT NULL)) OR (((changed_status)::text <> 'SUSPENDED'::text) AND (expired_dttm IS NULL)))),
    CONSTRAINT ck_account_histories_previous_status CHECK (((previous_status IS NULL) OR ((previous_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying, 'BANNED'::character varying, 'WITHDRAWN'::character varying])::text[])))),
    CONSTRAINT ck_account_histories_reason_type CHECK (((reason_type)::text = ANY ((ARRAY['SIGNUP'::character varying, 'USER_REQUEST'::character varying, 'POLICY_VIOLATION'::character varying, 'ADMIN_ACTION'::character varying, 'SUSPENSION_EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_account_histories_signup CHECK (((((reason_type)::text = 'SIGNUP'::text) AND (previous_status IS NULL) AND ((changed_status)::text = 'ACTIVE'::text) AND (reg_usr_seq IS NOT NULL)) OR (((reason_type)::text <> 'SIGNUP'::text) AND (previous_status IS NOT NULL))))
);


