-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    user_seq integer NOT NULL,
    nickname character varying(20) NOT NULL,
    phone_number character varying(16) NOT NULL,
    phone_verified_dttm timestamp with time zone NOT NULL,
    profile_image_seq bigint,
    birth_date date,
    gender character(1),
    role character varying(10) DEFAULT 'USER'::character varying NOT NULL,
    recent_search_terms character varying(100)[] DEFAULT (ARRAY[]::character varying[])::character varying(100)[] NOT NULL,
    account_status character varying(12) DEFAULT 'ACTIVE'::character varying NOT NULL,
    status_changed_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    reg_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    mod_dttm timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    mod_usr_seq integer,
    is_deleted boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_users_account_status CHECK (((account_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying, 'BANNED'::character varying, 'WITHDRAWN'::character varying])::text[]))),
    CONSTRAINT ck_users_gender CHECK (((gender IS NULL) OR (gender = ANY (ARRAY['M'::bpchar, 'F'::bpchar])))),
    CONSTRAINT ck_users_nickname_format CHECK (((nickname)::text ~ '^[가-힣A-Za-z0-9]+$'::text)),
    CONSTRAINT ck_users_nickname_length CHECK (((char_length((nickname)::text) >= 2) AND (char_length((nickname)::text) <= 20))),
    CONSTRAINT ck_users_phone_number CHECK (((phone_number)::text ~ '^\+[1-9][0-9]{7,14}$'::text)),
    CONSTRAINT ck_users_recent_search_terms CHECK ((cardinality(recent_search_terms) <= 10)),
    CONSTRAINT ck_users_role CHECK (((role)::text = ANY ((ARRAY['USER'::character varying, 'ARTIST'::character varying, 'ADMIN'::character varying])::text[])))
);


